<body>
    <!-- 修改加载容器的HTML结构 -->
    <div class="loading-container" id="loadingContainer">
        <div class="loading-spinner"></div>
        <div class="loading-text">资源加载中...</div>
        <div class="loading-progress">
            <div class="loading-progress-bar" id="loadingProgressBar"></div>
        </div>
        <div class="loading-percentage" id="loadingPercentage">0%</div>
    </div>

    <div class="status-container" id="statusContainer">
        <div class="background-slideshow" id="backgroundSlideshow"></div>
        <div class="status-content" id="status-content"></div>
    </div>

    <script>
        // 添加资源预加载系统
        class ResourceLoader {
            constructor() {
                this.totalResources = 0;
                this.loadedResources = 0;
                this.resources = {
                    images: [],
                    fonts: [
                        'ZCOOL QingKe HuangYou',
                        'Mochiy Pop One',
                        'Noto Sans SC',
                        'Gochi Hand',
                        'Yusei Magic',
                        'Ma Shan Zheng',
                        'Zen Maru Gothic',
                        'Zen Kurenaido'
                    ]
                };
            }

            async loadAll() {
                const imagePromises = backgrounds.map(url => this.loadImage(url));
                const fontPromises = this.resources.fonts.map(font => this.loadFont(font));

                // 计算总资源数
                this.totalResources = backgrounds.length + this.resources.fonts.length;

                try {
                    await Promise.all([...imagePromises, ...fontPromises]);
                    this.onLoadComplete();
                } catch (error) {
                    console.error('资源加载出错:', error);
                    this.onLoadComplete();
                }
            }

            loadImage(url) {
                return new Promise((resolve, reject) => {
                    const img = new Image();
                    img.onload = () => {
                        this.loadedResources++;
                        this.updateLoadingProgress();
                        resolve(img);
                    };
                    img.onerror = () => {
                        console.error(`图片加载失败: ${url}`);
                        this.loadedResources++;
                        this.updateLoadingProgress();
                        reject();
                    };
                    img.src = url;
                    this.resources.images.push(img);
                });
            }

            loadFont(fontFamily) {
                return new Promise((resolve) => {
                    document.fonts.load(`1em "${fontFamily}"`).then(() => {
                        this.loadedResources++;
                        this.updateLoadingProgress();
                        resolve();
                    }).catch(() => {
                        console.error(`字体加载失败: ${fontFamily}`);
                        this.loadedResources++;
                        this.updateLoadingProgress();
                        resolve();
                    });
                });
            }

            updateLoadingProgress() {
                const progress = Math.floor((this.loadedResources / this.totalResources) * 100);
                const progressBar = document.getElementById('loadingProgressBar');
                const percentageText = document.getElementById('loadingPercentage');

                if (progressBar && percentageText) {
                    progressBar.style.width = `${progress}%`;
                    percentageText.textContent = `${progress}%`;
                    document.querySelector('.loading-text').textContent = 
                        progress < 100 ? `资源加载中...` : '加载完成！';
                }
            }

            onLoadComplete() {
                // 隐藏加载动画
                const loadingContainer = document.getElementById('loadingContainer');
                const statusContainer = document.getElementById('statusContainer');

                loadingContainer.style.opacity = '0';
                setTimeout(() => {
                    loadingContainer.style.display = 'none';
                    statusContainer.classList.add('loaded');
                    // 初始化状态栏
                    initBackgroundSlideshow();
                    const statusData = parseStatusBar(statusString);
                    document.getElementById('status-content').innerHTML = generateStatusHTML(statusData);
                }, 500);
            }
        }

        // 在页面加载完成后开始加载资源
        window.addEventListener('load', () => {
            const loader = new ResourceLoader();
            loader.loadAll();
        });

        // 添加生成随机颜色的函数
        function generateRandomColor() {
            const hue = Math.floor(Math.random() * 360);
            const saturation = Math.floor(Math.random() * 30) + 70; // 70-100
            const lightness = Math.floor(Math.random() * 20) + 50;  // 50-70
            return `hsl(${hue}, ${saturation}%, ${lightness}%)`;
        }

        function parseStatusBar(statusString) {
            const data = {
                emotions: [],
                emotionPercentages: {},
                statusItems: {},
                choices: []
            };

            // 提取情绪列表和百分比
            const emotionListMatch = statusString.match(/<emotion-list>([\s\S]*?)<\/emotion-list>/);
            if (emotionListMatch) {
                const emotionContent = emotionListMatch[1].trim();
                const emotions = emotionContent.match(/\[(.*?)\]/g).map(e => e.replace(/[\[\]]/g, ''));
                emotions.forEach(emotion => {
                    const [name, percentage] = emotion.split('%');
                    data.emotions.push(name);
                    data.emotionPercentages[name] = parseInt(percentage || '0');
                });
            }

            // 提取状态项
            const lines = statusString.split('\n');
            for (let line of lines) {
                line = line.trim();
                if (line && !line.startsWith('<') && !line.endsWith('>') && line.includes('|')) {
                    const [key, ...values] = line.split('|');
                    data.statusItems[key] = values.join('|');
                }
            }

            // 提取选择项
            const choiceMatch = statusString.match(/<choice>([\s\S]*?)<\/choice>/);
            if (choiceMatch) {
                const choiceContent = choiceMatch[1].trim();
                data.choices = choiceContent.match(/\[(.*?)\]/g).map(c => c.replace(/[\[\]]/g, ''));
            }

            return data;
        }

        function generateStatusHTML(data) {
            let html = '';

            // 状态项
            Object.entries(data.statusItems).forEach(([key, value]) => {
                const randomColor = generateRandomColor();
                html += `<div class="status-item" style="border-left: 3px solid ${randomColor}"><strong style="color: ${randomColor}">${key}</strong><span>${value}</span></div>`;
            });

            // 情绪面板
            html += '<div class="emotion-papers" id="emotionPapers"><div class="emotion-papers-content">';
            data.emotions.forEach((emotion, index) => {
                const percentage = data.emotionPercentages[emotion];
                html += `<div class="emotion-paper" style="width: ${Math.max(100, percentage * 3)}px; 
                    transition-delay: ${index * 0.1}s">
                    ${emotion} ${percentage}%
                </div>`;
            });
            html += '</div></div>';

            // 选项面板
            html += '<div class="choice-container" id="choiceContainer"><div class="choice-content">';
            data.choices.forEach((choice, index) => {
                html += `<div class="choice-item" style="transition-delay: ${index * 0.1}s" 
                    onclick="makeChoice(${index})">${choice}</div>`;
            });
            html += '</div></div>';

            return html;
        }

        function makeChoice(index) {
            const choiceText = statusData.choices[index];
            sendOption(choiceText);
            // 关闭选项面板
            document.getElementById('choiceContainer').classList.remove('active');
        }

        function sendOption(optionText) {
            // 使用 triggerSlash 函数发送 Slash 命令
            triggerSlash(`/send ${optionText}`);
        }

        // 背景图片数组
        const backgrounds = [
            'https://files.catbox.moe/6kl6ab.png',
            'https://files.catbox.moe/6jhbtj.jpg',
            'https://files.catbox.moe/fmgagz.png',
            'https://files.catbox.moe/lt61op.jpg',
            'https://files.catbox.moe/4ij0j8.jpg',
            'https://files.catbox.moe/9aq6xl.png',
            'https://files.catbox.moe/rmo24t.jpg',
            'https://files.catbox.moe/av4rm3.jpg',
            'https://files.catbox.moe/eaba2p.jpg',
            'https://files.catbox.moe/6z08ke.jpg'
        ];

        // 修改背景初始化函数
        function initBackgroundSlideshow() {
            const slideshow = document.getElementById('backgroundSlideshow');
            backgrounds.forEach((bg, index) => {
                const img = document.createElement('img');
                img.src = bg;
                img.className = `background-image ${index === 0 ? 'active' : ''}`;
                slideshow.appendChild(img);
            });
            // 开始轮播
            setInterval(rotateBackground, 5000);
        }

        // 背景轮播
        let currentBgIndex = 0;
        function rotateBackground() {
            const images = document.getElementsByClassName('background-image');
            images[currentBgIndex].classList.remove('active');
            currentBgIndex = (currentBgIndex + 1) % backgrounds.length;
            images[currentBgIndex].classList.add('active');
        }

        // 添加长按相关变量
        let pressTimer;
        const longPressTime = 500; // 长按触发时间（毫秒）

        // 修改事件处理
        document.addEventListener('mousedown', function(e) {
            if (e.target.closest('.status-item')) {
                pressTimer = setTimeout(() => {
                    const emotionPapers = document.getElementById('emotionPapers');
                    const choiceContainer = document.getElementById('choiceContainer');
                    emotionPapers.classList.add('active');
                    choiceContainer.classList.remove('active');
                }, longPressTime);
            }
        });

        document.addEventListener('mouseup', function() {
            clearTimeout(pressTimer);
        });

        document.addEventListener('mouseleave', function() {
            clearTimeout(pressTimer);
        });

        // 修改点击事件
        document.addEventListener('click', function(e) {
            const emotionPapers = document.getElementById('emotionPapers');
            const choiceContainer = document.getElementById('choiceContainer');

            if (e.target.closest('.status-item')) {
                choiceContainer.classList.add('active');
                emotionPapers.classList.remove('active');
            } else if (emotionPapers.classList.contains('active')) {
                emotionPapers.classList.remove('active');
            } else if (choiceContainer.classList.contains('active')) {
                choiceContainer.classList.remove('active');
            }
        });

        // 添加触摸设备支持
        document.addEventListener('touchstart', function(e) {
            if (e.target.closest('.status-item')) {
                pressTimer = setTimeout(() => {
                    const emotionPapers = document.getElementById('emotionPapers');
                    const choiceContainer = document.getElementById('choiceContainer');
                    emotionPapers.classList.add('active');
                    choiceContainer.classList.remove('active');
                }, longPressTime);
            }
        });

        document.addEventListener('touchend', function() {
            clearTimeout(pressTimer);
        });

